from pathlib import Path
R=Path(__file__).resolve().parent.parent
out=['# -*- coding: utf-8 -*-']
for talk,base,met in ((0,1,True),(1,1,True),(1,0,False)):
 name='cs_part07_'+('talk' if talk else 'leave')+('_neutral' if base==0 else '')
