test='\n'.join(out).replace('    click until label cs_check_part07_pending','    click until label cs_check_part08_s54')
test=test.replace('    $ _test.timeout = 50.0','    $ _test.timeout = 50.0\n    $ _test.force = True')
(R/'qa/part07_routes_test.rpy').write_text(test,encoding='utf8')
print('Three part-7 cases and both morning CG branches generated')
